import { useRef, useState } from "react";
import type { Editor } from "@tiptap/core";
import { Button } from "./button";

type InlineFormatToolbarProps = {
    editor: Editor;
    onComment?: () => void;
};

function InlineFormatToolbar({ editor, onComment }: InlineFormatToolbarProps) {
    const [editingLink, setEditingLink] = useState(false);
    const [url, setUrl] = useState("");
    const [error, setError] = useState("");
    const selection = useRef({ from: 0, to: 0 });
    const actions = [
        { label: "굵게", mark: "bold",
            run: () => editor.chain().focus().toggleBold().run() },
        { label: "기울임", mark: "italic",
            run: () => editor.chain().focus().toggleItalic().run() },
        { label: "취소선", mark: "strike",
            run: () => editor.chain().focus().toggleStrike().run() },
        { label: "코드", mark: "code",
            run: () => editor.chain().focus().toggleCode().run() },
    ];
    function applyLink() {
        const href = url.trim();
        if (href && !/^(https?:\/\/|mailto:|\/[^/]|#)/i.test(href)) {
            setError("HTTP, HTTPS, mailto 또는 내부 경로를 입력하세요.");
            return;
        }
        const chain = editor.chain().focus().setTextSelection(selection.current);
        if (href) chain.setLink({ href }).run();
        else chain.unsetLink().run();
        setEditingLink(false);
        setError("");
    }
    return <div data-slot="inline-format-toolbar"
        className="grid max-w-[calc(100vw-1rem)] gap-2 rounded-md border border-border bg-surface p-1">
        <div role="toolbar" aria-label="선택 영역 서식"
            className="flex flex-wrap gap-1"
            onMouseDown={(event) => event.preventDefault()}>
            {actions.map((action) => <Button key={action.mark} className="h-8 px-2 text-xs"
                aria-pressed={editor.isActive(action.mark)}
                onClick={action.run}>{action.label}</Button>)}
            <Button className="h-8 px-2 text-xs" aria-pressed={editor.isActive("link")}
                onClick={() => {
                    selection.current = {
                        from: editor.state.selection.from,
                        to: editor.state.selection.to,
                    };
                    setUrl(editor.getAttributes("link").href ?? "");
                    setError(""); setEditingLink(true);
                }}>링크</Button>
            {onComment && <Button className="h-8 px-2 text-xs" onClick={onComment}>댓글</Button>}
        </div>
        {editingLink && <div className="flex flex-wrap gap-2">
            <input aria-label="링크 URL" value={url} autoFocus
                className="min-w-0 max-w-full rounded-sm border border-border bg-surface p-2"
                onChange={(event) => setUrl(event.target.value)}
                onKeyDown={(event) => {
                    if (event.nativeEvent.isComposing) return;
                    if (event.key === "Enter") {
                        event.preventDefault(); applyLink();
                    }
                    if (event.key === "Escape") {
                        setEditingLink(false);
                        editor.chain().focus()
                            .setTextSelection(selection.current).run();
                    }
                }} />
            <Button className="h-8 px-2 text-xs" onClick={applyLink}>적용</Button>
            <Button className="h-8 px-2 text-xs" onClick={() => {
                editor.chain().focus().setTextSelection(selection.current)
                    .unsetLink().run();
                setEditingLink(false);
            }}>링크 제거</Button>
            {error && <p role="alert" className="text-sm">{error}</p>}
        </div>}
    </div>;
}

export { InlineFormatToolbar };
export type { InlineFormatToolbarProps };
